define('taoClientDiagnostic/tools/diagnostic/diagnostic',['jquery', 'lodash', 'i18n', 'async', 'ui/component', 'core/logger', 'core/store', 'core/request', 'core/dataProvider/request', 'ui/dialog/alert', 'ui/feedback', 'util/url', 'taoClientDiagnostic/tools/performances/tester', 'taoClientDiagnostic/tools/bandwidth/tester', 'taoClientDiagnostic/tools/upload/tester', 'taoClientDiagnostic/tools/browser/tester', 'taoClientDiagnostic/tools/getStatus', 'taoClientDiagnostic/tools/getConfig', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/main', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/result', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/details', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/feedback', 'tpl!taoClientDiagnostic/tools/diagnostic/tpl/quality-bar', 'css!taoClientDiagnosticCss/diagnostics'], function ($, _, __, async, component, loggerFactory, store, request, requestData, dialogAlert, feedback, urlHelper, performancesTester, bandwidthTester, uploadTester, browserTester, getStatus, getConfig, mainTpl, resultTpl, detailsTpl, feedbackTpl, qualityBarTpl) {
  'use strict';
  var logger = loggerFactory('taoClientDiagnostic/diagnostic');
  var _defaults = {
    title: __('System Compatibility'),
    header: __('This tool will run a number of tests in order to establish how well your current environment is suitable to run the TAO platform.'),
    info: __('Be aware that these tests will take up to several minutes.'),
    button: __('Test system compatibility'),
    actionStore: 'storeData',
    actionSchool: 'schoolName',
    controller: 'DiagnosticChecker',
    extension: 'taoClientDiagnostic',
    actionDropId: 'deleteId',
    storeAllRuns: false,
    configurableText: {}
  };
  var _thresholds = [{
    threshold: 0,
    message: __('Your system requires a compatibility update, please contact your system administrator.'),
    type: 'error'
  }, {
    threshold: 33,
    message: __('Your system is not optimal, please contact your system administrator.'),
    type: 'warning'
  }, {
    threshold: 66,
    message: __('Your system is fully compliant.'),
    type: 'success'
  }];
  var diagnostic = {
    changeStatus(status) {
      if (this.is('rendered')) {
        this.controls.$status.html(status);
      }
      return this;
    },
    store(type, data, done) {
      var config = this.config;
      var url = urlHelper.route(config.actionStore, config.controller, config.extension, config.storeParams);
      data = _.omit(data, 'values');
      data.type = type;
      request({
        url,
        data,
        method: 'POST',
        noToken: true
      }).then(done).catch(err => {
        logger.error(err);
        feedback().error(__('Unable to save the results! Please check your connection.'));
        done();
      });
    },
    getCustomMsg(key) {
      return this.config.configurableText[key];
    },
    addCustomFeedbackMsg(status, msg) {
      if (this.hasFailed(status) && msg) {
        if (_.isFunction(status.customMsgRenderer)) {
          msg = status.customMsgRenderer(msg);
        }
        status.feedback = status.feedback || {};
        status.feedback.customMsg = msg;
      }
    },
    hasFailed(result) {
      return !(result && result.feedback && result.feedback.type === 'success');
    },
    addResult(result) {
      if (this.is('rendered')) {
        if (result.quality && result.quality.label && result.quality.label.toString().length > 2) {
          result.quality.wide = true;
        }
        var $main = $(resultTpl(result));
        var $result = $main.find('.result');
        if (result.feedback) {
          $result.append($(feedbackTpl(result.feedback)));
        }
        if (result.quality) {
          $result.append($(qualityBarTpl(result.quality)));
        }
        if (result.details) {
          $main.find('.details').append($(detailsTpl(result.details)));
        }
        var $indicator = $main.find('.quality-indicator');
        this.controls.$results.append($main);
        $main.fadeIn(() => {
          if ($indicator.length) {
            $indicator.animate({
              left: result.percentage * $main.outerWidth() / 100 - $indicator.outerWidth() / 2
            });
          }
        });
      }
      return this;
    },
    cleanUp() {
      this.controls.$results.empty();
      return this;
    },
    enable() {
      this.controls.$start.removeClass('hidden');
      return this;
    },
    disable() {
      this.controls.$start.addClass('hidden');
      return this;
    },
    prepare() {
      this.trigger('start');
      this.changeStatus(__('Starting...'));
      this.setState('running', true);
      this.setState('done', false);
      this.cleanUp();
      this.disable();
      return this;
    },
    finish() {
      var config = this.config;
      this.enable();
      if (config.storeAllRuns) {
        this.deleteIdentifier();
      }
      this.trigger('end');
      this.changeStatus(__('Done!'));
      this.setState('running', false);
      this.setState('done', true);
      return this;
    },
    deleteIdentifier() {
      var url = urlHelper.route(this.config.actionDropId, this.config.controller, this.config.extension);
      return request({
        url,
        method: 'POST',
        noToken: true
      });
    },
    run() {
      var information = [];
      var scores = {};
      var testers = [];
      var customInput = this.getCustomInput();
      var doRun = () => {
        var doCheck = (testerConfig, cb) => {
          var testerId = testerConfig.id;
          this.trigger('starttester', testerId);
          this.setState(testerId, true);
          var processTester = testerFactory => {
            var tester = testerFactory(getConfig(testerConfig, this.config), this);
            this.changeStatus(tester.labels.status);
            tester.start((status, details, results) => {
              if (testerConfig.customMsgKey) {
                var customMsg = this.getCustomMsg(testerConfig.customMsgKey);
                this.addCustomFeedbackMsg(status, customMsg);
              }
              _.forEach(details, info => information.push(info));
              scores[status.id] = status;
              this.trigger('endtester', testerId, status);
              this.setState(testerId, false);
              results = _.mapValues(results, value => {
                switch (typeof value) {
                  case 'boolean':
                    return value ? 1 : 0;
                  case 'object':
                    return JSON.stringify(value);
                }
                return value;
              });
              this.store(testerId, results, () => {
                this.addResult(status);
                cb();
              });
            });
          };
          var processFailure = err => {
            logger.error(err);
            feedback().error(__('Unable to process with the diagnostic tester %s. The tester module is unreachable.', testerId));
            cb();
          };
          require([testerConfig.tester], processTester, processFailure);
        };
        if (this.is('rendered')) {
          this.prepare();
          _.forEach(this.config.testers, (testerConfig, testerId) => {
            testerConfig.id = testerConfig.id || testerId;
            if (testerConfig.enabled) {
              testers.push(cb => doCheck(testerConfig, cb));
            }
          });
          async.series(testers, () => {
            var total = _.minBy(Object.values(scores), 'globalPercentage');
            var status = getStatus(total.globalPercentage, _thresholds);
            status.title = __('Total');
            status.id = 'total';
            this.addCustomFeedbackMsg(status, this.config.configurableText.diagTotalCheckResult);
            status.details = information;
            this.addResult(status);
            this.finish();
          });
        }
      };
      if (_.size(customInput) > 0) {
        this.store('custom_input', customInput, doRun);
      } else {
        doRun();
      }
      return this;
    },
    getCustomInput() {
      var vars = {};
      window.location.href.replace(location.hash, '').replace(/[?&]+([^=&]+)=?([^&]*)?/gi, (m, key, value) => {
        if (_.has(this.config['customInput'], key)) {
          vars[key] = typeof value !== 'undefined' ? value : '';
        }
      });
      return vars;
    }
  };
  return function diagnosticFactory(container, config) {
    if (config) {
      _.forEach(['title', 'header', 'footer', 'info', 'button'], name => {
        if (config[name]) {
          config[name] = __(config[name]);
        }
      });
    }
    var diagComponent = component(diagnostic, _defaults).setTemplate(mainTpl).on('destroy', function onDiagnosticDestroy() {
      this.controls = null;
    }).on('init', function onDiagnosticInit() {
      this.render(container);
    }).on('render', function onDiagnosticRender() {
      var runDiagnostics = data => {
        if (data && _.isPlainObject(data)) {
          this.config.storeParams = _.assign(this.config.storeParams || {}, data);
        }
        this.run();
      };
      var launch = () => runDiagnostics();
      var getControl = name => this.controls["$".concat(name)];
      function getInputValue(name) {
        var $control = getControl(name);
        return ($control && $control.val() || '').trim();
      }
      function setInputValue(name, value) {
        var $control = getControl(name);
        $control && $control.val(value);
      }
      function toggleControl(name, state) {
        var $control = getControl(name);
        if ($control) {
          if (typeof state === 'undefined') {
            state = !$control.is(':enabled');
          }
          if (state) {
            $control.prop('disabled', false);
          } else {
            $control.prop('disabled', true);
          }
        }
      }
      var requestSchoolName = values => {
        var componentConfig = this.config;
        return requestData(urlHelper.route(componentConfig.actionSchool, componentConfig.controller, componentConfig.extension), values, 'POST').then(data => {
          return {
            school_name: data,
            school_number: values.school_number
          };
        });
      };
      var manageSchoolProperties = (fields, validate) => {
        function toggleStart() {
          var allow = _.every(fields, getInputValue);
          toggleControl('start', allow);
          return allow;
        }
        function toggleFields(state) {
          _.forEach(fields, function (fieldName) {
            toggleControl(fieldName, state);
          });
        }
        _.forEach(fields, fieldName => {
          this.controls["$".concat(fieldName)] = this.getElement().find("[data-control=\"".concat(fieldName, "\"]")).on('keypress', e => {
            var shouldStart = e.which === 13;
            if (shouldStart) {
              e.preventDefault();
            }
            _.defer(() => {
              if (toggleStart() && shouldStart) {
                this.controls.$start.click();
              }
            });
          });
        });
        toggleStart();
        toggleFields(false);
        store('client-diagnostic').then(storage => {
          this.on('start.school', () => {
            _.forEach(fields, fieldName => {
              storage.setItem(fieldName, getInputValue(fieldName)).catch(error => {
                logger.error(error);
              });
            });
          });
          return Promise.all(_.map(fields, fieldName => {
            return storage.getItem(fieldName).then(value => {
              setInputValue(fieldName, value);
            });
          }));
        }).catch(error => {
          logger.error(error);
        }).then(() => {
          toggleFields(true);
          toggleStart();
        });
        launch = () => {
          var values = _.reduce(fields, (result, fieldName) => {
            result[fieldName] = getInputValue(fieldName);
            return result;
          }, {});
          this.changeStatus(__('Getting school name...')).cleanUp().disable();
          if (_.isFunction(validate)) {
            validate(values).then(runDiagnostics).catch(error => {
              var response = error.response || {};
              var message = response.errorMsg || response.errorMessage || __('An error occurred! Please verify your input!');
              dialogAlert(message);
              logger.error(error);
              this.changeStatus(__('Failed to get school name')).enable();
            });
          } else {
            runDiagnostics(values);
          }
        };
        this.on('start.school', () => {
          toggleFields(false);
        }).on('end.school', () => {
          toggleFields(true);
        });
      };
      this.controls = {
        $start: this.$component.find('[data-action="test-launcher"]'),
        $status: this.$component.find('.status h2'),
        $results: this.$component.find('.results')
      };
      this.controls.$start.on('click', () => {
        this.controls.$start.is(':enabled') && launch();
      });
      if (this.config.requireSchoolName) {
        if (this.config.validateSchoolName) {
          manageSchoolProperties(['school_number', 'school_pin'], requestSchoolName);
        } else {
          manageSchoolProperties(['school_name']);
        }
      }
      if (this.config.requireSchoolId) {
        manageSchoolProperties(['school_id', 'workstation']);
      }
      this.controls.$results.on('click', 'button[data-action="show-details"]', function onShowDetails() {
        var $btn = $(this).closest('button');
        var $result = $btn.closest('[data-result]');
        var $details = $result.find('.details');
        $details.removeClass('hidden');
        $btn.addClass('hidden');
        $result.find('[data-action="hide-details"]').removeClass('hidden');
      });
      this.controls.$results.on('click', 'button[data-action="hide-details"]', function onHideDetails() {
        var $btn = $(this).closest('button');
        var $result = $btn.closest('[data-result]');
        var $details = $result.find('.details');
        $details.addClass('hidden');
        $btn.addClass('hidden');
        $result.find('[data-action="show-details"]').removeClass('hidden');
      });
    });
    _.defer(() => diagComponent.init(config));
    return diagComponent;
  };
});
