define('taoClientDiagnostic/tools/stats',['lodash', 'taoClientDiagnostic/tools/fixedDecimals'], function (_, fixedDecimals) {
  'use strict';
  function valueGetter(name) {
    if ('function' === typeof name) {
      return name;
    }
    return item => item && item[name] || 0;
  }
  return function stats(list, fieldName, decimals) {
    var getValue = valueGetter(fieldName);
    var values = [];
    var min = Number.MAX_VALUE;
    var max = 0;
    var count = 0;
    var sum = _.reduce(list, (sum, item) => {
      if ('undefined' !== typeof item) {
        var value = getValue(item);
        values.push(value);
        min = Math.min(min, value);
        max = Math.max(max, value);
        sum += value;
        count++;
        return sum;
      }
    }, 0);
    var average = sum / (count || 1);
    var sum2 = values.reduce((sum, value) => {
      var diff = value - average;
      sum += diff * diff;
      return sum;
    }, 0);
    var variance = count > 1 ? Math.sqrt(sum2 / (count - 1)) : 0;
    values.sort();
    var middle = count / 2;
    var median = (values[Math.floor(middle)] + values[Math.ceil(middle)]) / 2;
    var results = {
      min,
      max,
      sum,
      count,
      average,
      median,
      variance
    };
    if (decimals) {
      _.forEach(results, (value, key) => {
        results[key] = fixedDecimals(value, decimals);
      });
    }
    results.values = list;
    return results;
  };
});
