define('taoClientDiagnostic/tools/upload/tester',['jquery', 'lodash', 'i18n', 'async', 'util/url', 'taoClientDiagnostic/tools/getConfig', 'taoClientDiagnostic/tools/getLabels', 'taoClientDiagnostic/tools/getStatus'], function ($, _, __, async, urlHelper, getConfig, getLabels, getStatus) {
  'use strict';
  var _kilo = 1024;
  var _mega = _kilo * _kilo;
  var data = [];
  var _defaults = {
    id: 'upload',
    size: _mega,
    optimal: _mega
  };
  var _thresholds = [{
    threshold: 0,
    message: __('Low upload speed'),
    type: 'error'
  }, {
    threshold: 33,
    message: __('Average upload speed'),
    type: 'warning'
  }, {
    threshold: 66,
    message: __('Good upload speed'),
    type: 'success'
  }];
  var _messages = [{
    title: __('Upload speed'),
    status: __('Checking upload speed...'),
    uploadAvg: __('Average upload speed'),
    uploadMax: __('Max upload speed')
  }];
  function generateStr(length) {
    var text = '';
    var possible = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
    for (var i = 0; i < length; i++) {
      text += possible.charAt(Math.floor(Math.random() * possible.length));
    }
    return text;
  }
  function upload(size) {
    var url = urlHelper.route('upload', 'CompatibilityChecker', 'taoClientDiagnostic', {
      cache: Date.now()
    });
    var str = generateStr(size);
    data = [];
    return $.ajax({
      url: url,
      type: 'POST',
      data: {
        upload: str
      },
      xhr: () => {
        var xhr = new window.XMLHttpRequest();
        var startTime = Date.now();
        xhr.upload.addEventListener('progress', evt => {
          if (evt.lengthComputable) {
            var passedTime = Date.now() - startTime;
            data.push({
              time: passedTime,
              loaded: evt.loaded,
              speed: evt.loaded * 8 / _mega / (passedTime / 1000)
            });
          }
        }, false);
        return xhr;
      }
    });
  }
  return function uploadTester(config) {
    var initConfig = getConfig(config, _defaults);
    var labels = getLabels(_messages, initConfig.level);
    return {
      start(done) {
        upload(parseInt(initConfig.size, 10)).then(() => {
          var totalSpeed = 0;
          var maxSpeed = 0;
          _.forEach(data, val => {
            totalSpeed += val.speed;
            if (maxSpeed < val.speed) {
              maxSpeed = Math.round(val.speed * 100) / 100;
            }
          });
          var avgSpeed = Math.round(totalSpeed / data.length * 100) / 100;
          var results = {
            max: maxSpeed,
            avg: avgSpeed,
            type: 'upload'
          };
          var status = this.getFeedback(avgSpeed);
          var summary = this.getSummary(results);
          done(status, summary, results);
        });
      },
      get labels() {
        return labels;
      },
      getSummary(results) {
        return {
          uploadAvg: {
            message: labels.uploadAvg,
            value: "".concat(results.avg, " Mbps")
          },
          uploadMax: {
            message: labels.uploadMax,
            value: "".concat(results.max, " Mbps")
          }
        };
      },
      getFeedback(result) {
        var optimal = initConfig.optimal / _mega;
        var status = getStatus(100 / optimal * result, _thresholds);
        status.id = initConfig.id;
        status.title = labels.title;
        return status;
      }
    };
  };
});
